<section class="ro-panel" x-data="refugioOrders">
<header class="ro-section-heading"><div><h2>Pedidos y pre-pedidos</h2><p>Filtra por fecha de creación del pedido.</p></div></header>
<form class="ro-date-fields mb-4" @submit.prevent="load()"><label>Desde<input type="date" x-model="from" @change="load()"></label><label>Hasta<input type="date" x-model="until" @change="load()"></label><button type="button" class="ro-button" @click="reset()">Restablecer</button></form>
<p class="ro-error" role="alert" x-show="error" x-text="error" x-cloak></p><p role="status" x-show="loading">Consultando pedidos…</p>
<div class="blade-table-wrap" :aria-busy="loading"><table class="blade-table"><thead><tr><th>Folio</th><th>Fecha</th><th>Correo</th><th>Estado</th><th>Moneda</th><th>Total</th></tr></thead><tbody><template x-for="order in orders" :key="order.id"><tr><td x-text="order.order_number"></td><td x-text="date(order.created_at)"></td><td x-text="order.customer_email"></td><td x-text="order.status"></td><td x-text="order.currency"></td><td x-text="order.grand_total"></td></tr></template></tbody></table></div>
<p x-show="!loading && !error && !orders.length">Sin pedidos para estas fechas.</p><div class="blade-actions mt-4"><button class="ro-button" type="button" :disabled="loading || page <= 1" @click="load(page-1)">Anterior</button><span x-text="page + ' / ' + last"></span><button class="ro-button" type="button" :disabled="loading || page >= last" @click="load(page+1)">Siguiente</button></div></section>